sys_ux_data_broker_scriptlet.script:
var CreateCaseHandler = Class.create();
CreateCaseHandler.prototype = {
    initialize: function() {},

    /**
     * @param {Object} input - Input object from UI Builder
     * @returns {Object} result - Response object
     */
    createRecords: function(input) {
        var result = {};

        try {
            // Create record in first custom table
            var rec1 = new GlideRecord('x_your_scope_custom_table_1');
            rec1.initialize();
            rec1.email = input.email_id; // Example field
            rec1.insert();

            // Create record in second custom table
            // var rec2 = new GlideRecord('x_your_scope_custom_table_2');
            // rec2.initialize();
            // rec2.related_case = rec1SysId; // Linking to first record
            // rec2.status = input.status; // Example field
            // rec2.insert();

            result.success = true;
            result.message = "Records created successfully.";
        } catch (e) {
            result.success = false;
            result.message = "Error: " + e.message;
        }

        return result;
    },

    type: 'CreateCaseHandler'
};
